    if (!target) return;

    const restored = {
      ...target,
      isArchived: false,
      expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
    };

    const updatedArchived = archivedStoriesList.filter((s) => s.id !== storyId);
    const updatedActive = [restored, ...storiesList];

    setArchivedStoriesList(updatedArchived);
    setStoriesList(updatedActive);
    persistArchivedStories(updatedArchived);
    persistStories(updatedActive);

