  // Friend requests with details
  const receivedRequestsWithDetails = useMemo(() => {
    return receivedFriendRequests.map((reqUsername) => {
      const cleanName = String(reqUsername).toLowerCase();
      const u = discoveryUsers.find(
        (user) => (user.username || '').toLowerCase() === cleanName
      );
      return {
        id: u?.id || cleanName,
        username: cleanName,
        displayName: u?.displayName || reqUsername,
        avatar: u?.avatar || null,
        status: u?.status || '',
        friends: u?.friends || [],
      };
    });
  }, [receivedFriendRequests, discoveryUsers]);

  const filteredReceivedRequests = useMemo(() => {
    if (!searchFriendsQuery.trim()) return receivedRequestsWithDetails;
    const q = searchFriendsQuery.trim().toLowerCase();
    return receivedRequestsWithDetails.filter(
      (r) => r.username.toLowerCase().includes(q) || r.displayName.toLowerCase().includes(q)
    );
  }, [receivedRequestsWithDetails, searchFriendsQuery]);

  const sentRequestsWithDetails = useMemo(() => {
    return sentFriendRequests.map((reqUsername) => {
      const cleanName = String(reqUsername).toLowerCase();
      const u = discoveryUsers.find(
        (user) => (user.username || '').toLowerCase() === cleanName
      );
      return {
        id: u?.id || cleanName,
        username: cleanName,
        displayName: u?.displayName || reqUsername,
        avatar: u?.avatar || null,
        status: u?.status || '',
        friends: u?.friends || [],
      };
    });
  }, [sentFriendRequests, discoveryUsers]);

  const filteredSentRequests = useMemo(() => {
    if (!searchFriendsQuery.trim()) return sentRequestsWithDetails;
    const q = searchFriendsQuery.trim().toLowerCase();
    return sentRequestsWithDetails.filter(
      (r) => r.username.toLowerCase().includes(q) || r.displayName.toLowerCase().includes(q)
    );
  }, [sentRequestsWithDetails, searchFriendsQuery]);

  // Suggested connections: users not yet friends, not pending, ranked by mutual friends
  const suggestedConnections = useMemo(() => {
    if (!loggedInUser) return [];
    const myUsername = loggedInUser.toLowerCase();
    const myFriendsSet = new Set(effectiveFriendsList.map((f) => f.toLowerCase()));
    const sentSet = new Set(sentFriendRequests.map((f) => f.toLowerCase()));
    const receivedSet = new Set(receivedFriendRequests.map((f) => f.toLowerCase()));

    const candidates = discoveryUsers.filter((u) => {
      const uName = (u.username || '').toLowerCase();
      if (!uName || uName === myUsername) return false;
      if (myFriendsSet.has(uName)) return false;
      if (sentSet.has(uName) || receivedSet.has(uName)) return false;
      return true;
    });

    return candidates
      .map((u) => {
        const mutual = getMutualFriends(u);
        const isFollowingUser = followingList.some((f) => f.toLowerCase() === u.username.toLowerCase());
        return {
          ...u,
          mutualFriends: mutual,
          mutualCount: mutual.length,
          isFollowingUser,
        };
      })
      .sort((a, b) => b.mutualCount - a.mutualCount);
  }, [
    loggedInUser,
    discoveryUsers,
    effectiveFriendsList,
    sentFriendRequests,
    receivedFriendRequests,
    followingList,
    getMutualFriends,
  ]);

  const filteredSuggestions = useMemo(() => {
    if (!searchFriendsQuery.trim()) return suggestedConnections;
    const q = searchFriendsQuery.trim().toLowerCase();
    return suggestedConnections.filter(
      (s) => s.username.toLowerCase().includes(q) || s.displayName.toLowerCase().includes(q)
    );
  }, [suggestedConnections, searchFriendsQuery]);

  const allSocialUsers = discoveryUsers.filter(
    (u) => u.username && u.username.toLowerCase() !== (loggedInUser || '').toLowerCase()
  );

  const filteredSocialUsers = allSocialUsers.filter((u) => {
    if (!searchFriendsQuery.trim()) return true;
    const q = searchFriendsQuery.trim().toLowerCase();
    return (
      (u.username && u.username.toLowerCase().includes(q)) ||
      (u.displayName && u.displayName.toLowerCase().includes(q))
    );
  });

  const myAuthoredPosts = posts.filter(
    (p) => String(p.author || '').toLowerCase() === String(loggedInUser || '').toLowerCase()
  );

  const myPhotosPosts = myAuthoredPosts.filter((p) => {
    const isVideo = Boolean(
      p.video ||
      p.mediaType === 'video' ||
      (p.media && (p.media.startsWith('data:video') || p.media.endsWith('.mp4') || p.media.endsWith('.webm') || p.media.endsWith('.mov') || p.media.includes('/video/')))
    );
    return !isVideo && Boolean(p.image || p.media);
  });

  const allCommunityPhotos = useMemo(() => {
    return posts.filter((p) => {
      const isVideo = Boolean(
        p.video ||
        p.mediaType === 'video' ||
        (p.media && (p.media.startsWith('data:video') || p.media.endsWith('.mp4') || p.media.endsWith('.webm') || p.media.endsWith('.mov') || p.media.includes('/video/')))
      );
      return !isVideo && Boolean(p.image || p.media);
    });
  }, [posts]);

  const filteredCommunityPhotos = useMemo(() => {
    let list = photoSharingTab === 'my-photos' ? myPhotosPosts : allCommunityPhotos;

    if (photoCategoryFilter !== 'all') {
      const tag = `#${photoCategoryFilter}`.toLowerCase();
      list = list.filter((p) => {
        const content = String(p.content || '').toLowerCase();
        return content.includes(tag) || content.includes(photoCategoryFilter.toLowerCase());
      });
    }

    if (photoSearchQuery.trim()) {
      const q = photoSearchQuery.trim().toLowerCase();
      const cleanQ = q.replace(/^@/, '');
      list = list.filter((p) => {
        const content = String(p.content || '').toLowerCase();
        const author = String(p.author || '').toLowerCase();
        const authorName = String(p.authorName || '').toLowerCase();
        return content.includes(q) || author.includes(cleanQ) || authorName.includes(cleanQ);
      });
    }

    return list;
  }, [allCommunityPhotos, myPhotosPosts, photoSharingTab, photoCategoryFilter, photoSearchQuery]);

  const allCommunityVideos = useMemo(() => {
    const realVideos = posts.filter((p) => {
      return Boolean(
        p.video ||
        p.mediaType === 'video' ||
        (p.media &&
          (p.media.startsWith('data:video') ||
            p.media.endsWith('.mp4') ||
            p.media.endsWith('.webm') ||
            p.media.endsWith('.mov') ||
            p.media.includes('/video/') ||
            p.media.includes('youtube.com') ||
            p.media.includes('youtu.be') ||
            p.media.includes('vimeo.com')))
      );
    });

    const realIds = new Set(realVideos.map((v) => v.id));
    const samples = DEFAULT_COMMUNITY_VIDEOS
      .filter((s) => !realIds.has(s.id) && !sampleVideoInteractions[s.id]?.isDeleted)
      .map((s) => {
        const override = sampleVideoInteractions[s.id];
        if (override) {
          return {
            ...s,
            ...override,
          };
        }
        return s;
      });

    return [...realVideos, ...samples];
  }, [posts, sampleVideoInteractions]);

  const myVideosPosts = useMemo(() => {
    return allCommunityVideos.filter(
      (p) => String(p.author || '').toLowerCase() === String(loggedInUser || '').toLowerCase()
    );
  }, [allCommunityVideos, loggedInUser]);

  const trendingVideos = useMemo(() => {
    return [...allCommunityVideos].sort((a, b) => {
      const likesA = (a.likes || []).length || a.likesCount || 0;
      const likesB = (b.likes || []).length || b.likesCount || 0;
      const commentsA = (a.comments || []).length || a.commentsCount || 0;
      const commentsB = (b.comments || []).length || b.commentsCount || 0;
      return (likesB * 2 + commentsB) - (likesA * 2 + commentsA);
    });
  }, [allCommunityVideos]);

  const filteredCommunityVideos = useMemo(() => {
    let list = allCommunityVideos;
    if (videoSharingTab === 'trending') {
      list = trendingVideos;
    } else if (videoSharingTab === 'my-videos') {
      list = myVideosPosts;
    }

    if (videoCategoryFilter !== 'all') {
      const tag = `#${videoCategoryFilter}`.toLowerCase();
      list = list.filter((p) => {
        const content = String(p.content || '').toLowerCase();
        const title = String(p.title || '').toLowerCase();
        return (
          content.includes(tag) ||
          content.includes(videoCategoryFilter.toLowerCase()) ||
          title.includes(videoCategoryFilter.toLowerCase())
        );
      });
    }

    if (videoSearchQuery.trim()) {
      const q = videoSearchQuery.trim().toLowerCase();
      const cleanQ = q.replace(/^@/, '');
      list = list.filter((p) => {
        const content = String(p.content || '').toLowerCase();
        const title = String(p.title || '').toLowerCase();
        const author = String(p.author || '').toLowerCase();
        const authorName = String(p.authorName || '').toLowerCase();
        return (
          content.includes(q) ||
          title.includes(q) ||
          author.includes(cleanQ) ||
          authorName.includes(cleanQ)
        );
      });
    }

    return list;
  }, [allCommunityVideos, trendingVideos, myVideosPosts, videoSharingTab, videoCategoryFilter, videoSearchQuery]);

  // ==========================================
