  const handleEditCommunitySubmit = async (e) => {
    if (e) e.preventDefault();
    if (!editingCommunity) return;

    const commId = editingCommunity._id || editingCommunity.id;
    const cleanName = editCommunityName.trim();
    if (!cleanName) {
      setEditCommunityFeedback({ type: 'error', text: 'Community name is required.' });
      return;
    }
    if (cleanName.length < 2) {
      setEditCommunityFeedback({ type: 'error', text: 'Community name must be at least 2 characters.' });
      return;
    }

    setIsSubmittingEditCommunity(true);
    setEditCommunityFeedback(null);

    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'user').trim();

    const payload = {
      name: cleanName,
      description: editCommunityDesc.trim(),
      category: editCommunityCategory,
      privacy: editCommunityPrivacy,
      avatar: editCommunityAvatar || '',
      user: currentUser,
    };

    try {
      const res = await fetch(`/api/communities/${commId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (res.ok && data.success && data.community) {
        setCommunitiesList((prev) => {
          const updated = prev.map((c) =>
            ((c._id || c.id) === (data.community._id || data.community.id || commId))
              ? { ...c, ...data.community }
              : c
          );
          try {
            localStorage.setItem('planet_communities', JSON.stringify(updated));
          } catch { }
          return updated;
        });
        setEditCommunityFeedback({ type: 'success', text: 'Community details updated successfully! ✨' });
        setTimeout(() => {
          handleCloseEditCommunity();
        }, 800);
      } else {
        setEditCommunityFeedback({
          type: 'error',
          text: data.error || data.message || 'Failed to update community details.',
        });
      }
    } catch {
      // Offline fallback: update local state
      setCommunitiesList((prev) => {
        const updated = prev.map((c) =>
          ((c._id || c.id) === commId)
            ? {
              ...c,
              name: cleanName,
              description: editCommunityDesc.trim(),
              category: editCommunityCategory,
              privacy: editCommunityPrivacy,
              avatar: editCommunityAvatar || '',
              updatedAt: new Date().toISOString(),
            }
            : c
        );
        try {
          localStorage.setItem('planet_communities', JSON.stringify(updated));
        } catch { }
        return updated;
      });
      setEditCommunityFeedback({ type: 'success', text: 'Community details updated successfully!' });
      setTimeout(() => {
        handleCloseEditCommunity();
      }, 800);
    } finally {
      setIsSubmittingEditCommunity(false);
    }
  };

  const handleDeleteCommunity = async (communityId) => {
    if (!window.confirm('Are you sure you want to delete this community?')) return;
    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'user').trim();
    try {
      await fetch(`/api/communities/${communityId}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user: currentUser }),
      });
    } catch { }
    setCommunitiesList((prev) => {
      const updated = prev.filter((c) => (c._id || c.id) !== communityId);
      try {
        localStorage.setItem('planet_communities', JSON.stringify(updated));
      } catch { }
      return updated;
    });
  };

  const handleJoinCommunity = async (communityId) => {
    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'user').trim();
    if (!currentUser) return;

    // In Free plan, user can join up to 5 groups
    if (currentPlanId === 'free') {
      const cleanUser = currentUser.toLowerCase();
      const targetComm = (communitiesList || []).find((c) => (c._id || c.id) === communityId);
      const isAlreadyMember = targetComm && Array.isArray(targetComm.members) && targetComm.members.some((m) => {
        const u = typeof m === 'string' ? m : (m?.username || m?.name || '');
        return u.trim().toLowerCase() === cleanUser;
      });

      if (!isAlreadyMember && getJoinedGroupsCount() >= 5) {
        setShowJoinGroupLimitUpgradeModal(true);
        return;
      }
    }

    setJoiningCommunityId(communityId);
    try {
      const res = await fetch(`/api/communities/${communityId}/join`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user: currentUser, plan: currentPlanId }),
      });
      const data = await res.json();
      if (!res.ok && (data.limitReached || (data.error && data.error.includes('limit')))) {
        setShowJoinGroupLimitUpgradeModal(true);
        return;
      }
      if (res.ok && data.success && data.community) {
        setCommunitiesList((prev) => {
          const updated = prev.map((c) =>
            ((c._id || c.id) === communityId ? { ...c, ...data.community } : c)
          );
          try {
            localStorage.setItem('planet_communities', JSON.stringify(updated));
          } catch { }
          return updated;
        });
      } else {
        // Fallback / local update
        setCommunitiesList((prev) => {
          const updated = prev.map((c) => {
            if ((c._id || c.id) === communityId) {
              const currentMembers = Array.isArray(c.members) ? [...c.members] : [];
              const exists = currentMembers.some(
                (m) => (m.username && m.username.toLowerCase() === currentUser.toLowerCase()) || m === currentUser
              );
              if (!exists) {
                currentMembers.push({ username: currentUser.toLowerCase(), role: 'member', joinedAt: new Date() });
              }
              return {
                ...c,
                members: currentMembers,
                memberCount: currentMembers.length,
              };
            }
            return c;
          });
          try {
            localStorage.setItem('planet_communities', JSON.stringify(updated));
          } catch { }
          return updated;
        });
      }
    } catch {
      // Offline fallback
      setCommunitiesList((prev) => {
        const updated = prev.map((c) => {
          if ((c._id || c.id) === communityId) {
            const currentMembers = Array.isArray(c.members) ? [...c.members] : [];
            const exists = currentMembers.some(
              (m) => (m.username && m.username.toLowerCase() === currentUser.toLowerCase()) || m === currentUser
            );
            if (!exists) {
              currentMembers.push({ username: currentUser.toLowerCase(), role: 'member', joinedAt: new Date() });
            }
            return {
              ...c,
              members: currentMembers,
              memberCount: currentMembers.length,
            };
          }
          return c;
        });
        try {
          localStorage.setItem('planet_communities', JSON.stringify(updated));
        } catch { }
        return updated;
      });
    } finally {
      setJoiningCommunityId(null);
    }
  };

