  const handlePublishAnnouncementSubmit = async (e) => {
    if (e) e.preventDefault();
    if (!activeCommunityFeed) return;
    const commId = activeCommunityFeed._id || activeCommunityFeed.id;
    const cleanTitle = newAnnouncementTitle.trim();
    const cleanContent = newAnnouncementContent.trim();
    if (!cleanTitle) {
      setAnnouncementFeedback({ type: 'error', text: 'Announcement title is required.' });
      return;
    }
    if (!cleanContent) {
      setAnnouncementFeedback({ type: 'error', text: 'Announcement content is required.' });
      return;
    }

    setIsPublishingAnnouncement(true);
    setAnnouncementFeedback(null);

    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'user').trim().toLowerCase();
    const currentDisplayName = displayName || currentUser;

    const payload = {
      title: cleanTitle,
      content: cleanContent,
      author: currentUser,
      authorName: currentDisplayName,
      authorAvatar: userAvatar || '',
      tag: newAnnouncementTag,
      isPinned: newAnnouncementIsPinned,
    };

    try {
      const res = await fetch(`/api/communities/${commId}/announcements`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      const createdAnnouncement = data?.announcement || {
        _id: 'ann_' + Date.now(),
        ...payload,
        createdAt: new Date().toISOString(),
      };

      setActiveCommunityFeed((prev) => {
        if (!prev) return prev;
        const currentAnnouncements = Array.isArray(prev.announcements) ? [...prev.announcements] : [];
        return {
          ...prev,
          announcements: [createdAnnouncement, ...currentAnnouncements],
        };
      });

      setCommunitiesList((prev) => {
        const updated = prev.map((c) => {
          if ((c._id || c.id) === commId) {
            const currentAnnouncements = Array.isArray(c.announcements) ? [...c.announcements] : [];
            return {
              ...c,
              announcements: [createdAnnouncement, ...currentAnnouncements],
            };
          }
          return c;
        });
        try {
          localStorage.setItem('planet_communities', JSON.stringify(updated));
        } catch { }
        return updated;
      });

      setAnnouncementFeedback({ type: 'success', text: 'Community announcement published successfully! 📢' });
      setTimeout(() => {
        handleCloseCreateAnnouncement();
      }, 700);
    } catch {
      const localAnnouncement = {
        _id: 'ann_' + Date.now(),
        ...payload,
        createdAt: new Date().toISOString(),
      };
      setActiveCommunityFeed((prev) => {
        if (!prev) return prev;
        const currentAnnouncements = Array.isArray(prev.announcements) ? [...prev.announcements] : [];
        return {
          ...prev,
          announcements: [localAnnouncement, ...currentAnnouncements],
        };
      });
      setCommunitiesList((prev) => {
        const updated = prev.map((c) => {
          if ((c._id || c.id) === commId) {
            const currentAnnouncements = Array.isArray(c.announcements) ? [...c.announcements] : [];
            return {
              ...c,
              announcements: [localAnnouncement, ...currentAnnouncements],
            };
          }
          return c;
        });
        try {
          localStorage.setItem('planet_communities', JSON.stringify(updated));
        } catch { }
        return updated;
      });
      setAnnouncementFeedback({ type: 'success', text: 'Community announcement published!' });
      setTimeout(() => {
        handleCloseCreateAnnouncement();
      }, 700);
    } finally {
      setIsPublishingAnnouncement(false);
    }
  };

  const handleDeleteAnnouncement = async (announcementId) => {
    if (!window.confirm('Delete this announcement?')) return;
    if (!activeCommunityFeed) return;
    const commId = activeCommunityFeed._id || activeCommunityFeed.id;

    try {
      await fetch(`/api/communities/${commId}/announcements/${announcementId}`, {
        method: 'DELETE',
      });
    } catch { }

    setActiveCommunityFeed((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        announcements: (prev.announcements || []).filter(
          (a) => (a._id || a.id) !== announcementId
        ),
      };
    });

    setCommunitiesList((prev) => {
      const updated = prev.map((c) => {
        if ((c._id || c.id) === commId) {
          return {
            ...c,
            announcements: (c.announcements || []).filter(
              (a) => (a._id || a.id) !== announcementId
            ),
          };
        }
        return c;
      });
      try {
        localStorage.setItem('planet_communities', JSON.stringify(updated));
      } catch { }
      return updated;
    });
  };

  const handleOpenCreateDiscussion = (preselectedCommunity = null) => {
    setNewDiscussionTitle('');
    setNewDiscussionContent('');
    setNewDiscussionCategory('General');
    const targetId = preselectedCommunity?._id || preselectedCommunity?.id ||
      activeCommunityFeed?._id || activeCommunityFeed?.id ||
      (communitiesList[0]?._id || communitiesList[0]?.id || '');
    setNewDiscussionCommunityId(targetId);
    setDiscussionFeedback(null);
    setShowCreateDiscussionModal(true);
  };

  const handleCloseCreateDiscussion = () => {
    setShowCreateDiscussionModal(false);
    setDiscussionFeedback(null);
  };

  const handleCreateDiscussionSubmit = async (e) => {
    if (e) e.preventDefault();
    const commId = (activeCommunityFeed?._id || activeCommunityFeed?.id) || newDiscussionCommunityId || (communitiesList[0]?._id || communitiesList[0]?.id);
    if (!commId) {
      setDiscussionFeedback({ type: 'error', text: 'Please select a community for this discussion.' });
      return;
    }
    const cleanTitle = newDiscussionTitle.trim();
    const cleanContent = newDiscussionContent.trim();
    if (!cleanTitle) {
      setDiscussionFeedback({ type: 'error', text: 'Discussion title is required.' });
      return;
    }
    if (!cleanContent) {
      setDiscussionFeedback({ type: 'error', text: 'Discussion content is required.' });
      return;
    }

    setIsSubmittingDiscussion(true);
    setDiscussionFeedback(null);

    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'user').trim().toLowerCase();
    const currentDisplayName = displayName || currentUser;

    const payload = {
      title: cleanTitle,
      content: cleanContent,
      author: currentUser,
      authorName: currentDisplayName,
      authorAvatar: userAvatar || '',
      category: newDiscussionCategory,
    };

    try {
      const res = await fetch(`/api/communities/${commId}/discussions`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      const createdDiscussion = data?.discussion || {
        _id: 'disc_' + Date.now(),
        ...payload,
        likes: [],
        likesCount: 0,
        comments: [],
        commentsCount: 0,
        createdAt: new Date().toISOString(),
      };

      if (activeCommunityFeed && (activeCommunityFeed._id || activeCommunityFeed.id) === commId) {
        setActiveCommunityFeed((prev) => {
          if (!prev) return prev;
          const currentDiscussions = Array.isArray(prev.discussions) ? [...prev.discussions] : [];
          return {
            ...prev,
            discussions: [createdDiscussion, ...currentDiscussions],
          };
        });
      }

      setCommunitiesList((prev) => {
        const updated = prev.map((c) => {
          if ((c._id || c.id) === commId) {
            const currentDiscussions = Array.isArray(c.discussions) ? [...c.discussions] : [];
            return {
              ...c,
              discussions: [createdDiscussion, ...currentDiscussions],
            };
          }
          return c;
        });
        try {
          localStorage.setItem('planet_communities', JSON.stringify(updated));
        } catch { }
        return updated;
      });

      setDiscussionFeedback({ type: 'success', text: 'Discussion posted to community feed! 💬' });
      setTimeout(() => {
        handleCloseCreateDiscussion();
      }, 700);
    } catch {
      const localDiscussion = {
        _id: 'disc_' + Date.now(),
        ...payload,
        likes: [],
        likesCount: 0,
        comments: [],
        commentsCount: 0,
        createdAt: new Date().toISOString(),
      };
      if (activeCommunityFeed && (activeCommunityFeed._id || activeCommunityFeed.id) === commId) {
        setActiveCommunityFeed((prev) => {
          if (!prev) return prev;
          const currentDiscussions = Array.isArray(prev.discussions) ? [...prev.discussions] : [];
          return {
            ...prev,
            discussions: [localDiscussion, ...currentDiscussions],
          };
        });
      }
      setCommunitiesList((prev) => {
        const updated = prev.map((c) => {
          if ((c._id || c.id) === commId) {
            const currentDiscussions = Array.isArray(c.discussions) ? [...c.discussions] : [];
            return {
              ...c,
              discussions: [localDiscussion, ...currentDiscussions],
            };
          }
          return c;
        });
        try {
          localStorage.setItem('planet_communities', JSON.stringify(updated));
        } catch { }
        return updated;
      });
      setDiscussionFeedback({ type: 'success', text: 'Discussion posted!' });
      setTimeout(() => {
        handleCloseCreateDiscussion();
      }, 700);
    } finally {
      setIsSubmittingDiscussion(false);
    }
  };

  const handleToggleDiscussionLike = async (discussionId) => {
    if (!activeCommunityFeed) return;
    const commId = activeCommunityFeed._id || activeCommunityFeed.id;
    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'user').trim().toLowerCase();

    // Optimistically update
    setActiveCommunityFeed((prev) => {
      if (!prev) return prev;
      const updatedDiscussions = (prev.discussions || []).map((d) => {
        if ((d._id || d.id) === discussionId) {
          const currentLikes = Array.isArray(d.likes) ? [...d.likes] : [];
          const idx = currentLikes.indexOf(currentUser);
          if (idx > -1) {
            currentLikes.splice(idx, 1);
          } else {
            currentLikes.push(currentUser);
          }
          return {
            ...d,
            likes: currentLikes,
            likesCount: currentLikes.length,
          };
        }
        return d;
      });
      return { ...prev, discussions: updatedDiscussions };
    });

    try {
      await fetch(`/api/communities/${commId}/discussions/${discussionId}/like`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user: currentUser }),
      });
    } catch { }
  };

  const handleDiscussionCommentChange = (discussionId, value) => {
    setDiscussionCommentInputs((prev) => ({
      ...prev,
      [discussionId]: value,
    }));
  };

  const handleToggleDiscussionComments = (discussionId) => {
    setExpandedDiscussionComments((prev) => ({
      ...prev,
      [discussionId]: !prev[discussionId],
    }));
  };

  const handleSubmitDiscussionComment = async (e, discussionId) => {
    if (e) e.preventDefault();
    if (!activeCommunityFeed) return;
    const commId = activeCommunityFeed._id || activeCommunityFeed.id;
    const content = (discussionCommentInputs[discussionId] || '').trim();
    if (!content) return;

    setIsSubmittingComment((prev) => ({ ...prev, [discussionId]: true }));
    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'user').trim().toLowerCase();
    const currentDisplayName = displayName || currentUser;

    const payload = {
      content,
      author: currentUser,
      authorName: currentDisplayName,
      authorAvatar: userAvatar || '',
    };

    try {
      const res = await fetch(`/api/communities/${commId}/discussions/${discussionId}/comment`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      const newComment = data?.comment || {
        _id: 'com_' + Date.now(),
        ...payload,
        createdAt: new Date().toISOString(),
      };

      setActiveCommunityFeed((prev) => {
        if (!prev) return prev;
        const updatedDiscussions = (prev.discussions || []).map((d) => {
          if ((d._id || d.id) === discussionId) {
            const currentComments = Array.isArray(d.comments) ? [...d.comments] : [];
            currentComments.push(newComment);
            return {
              ...d,
              comments: currentComments,
              commentsCount: currentComments.length,
            };
          }
          return d;
        });
        return { ...prev, discussions: updatedDiscussions };
      });

      // Clear input and ensure comments expanded
      setDiscussionCommentInputs((prev) => ({ ...prev, [discussionId]: '' }));
      setExpandedDiscussionComments((prev) => ({ ...prev, [discussionId]: true }));
    } catch {
      const localComment = {
        _id: 'com_' + Date.now(),
        ...payload,
        createdAt: new Date().toISOString(),
      };
      setActiveCommunityFeed((prev) => {
        if (!prev) return prev;
        const updatedDiscussions = (prev.discussions || []).map((d) => {
          if ((d._id || d.id) === discussionId) {
            const currentComments = Array.isArray(d.comments) ? [...d.comments] : [];
            currentComments.push(localComment);
            return {
              ...d,
              comments: currentComments,
              commentsCount: currentComments.length,
            };
          }
          return d;
        });
        return { ...prev, discussions: updatedDiscussions };
      });
      setDiscussionCommentInputs((prev) => ({ ...prev, [discussionId]: '' }));
      setExpandedDiscussionComments((prev) => ({ ...prev, [discussionId]: true }));
    } finally {
      setIsSubmittingComment((prev) => ({ ...prev, [discussionId]: false }));
    }
  };

  const handleDeleteDiscussion = async (discussionId) => {
    if (!window.confirm('Delete this discussion thread?')) return;
    if (!activeCommunityFeed) return;
    const commId = activeCommunityFeed._id || activeCommunityFeed.id;

    try {
      await fetch(`/api/communities/${commId}/discussions/${discussionId}`, {
        method: 'DELETE',
      });
    } catch { }

    setActiveCommunityFeed((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        discussions: (prev.discussions || []).filter(
          (d) => (d._id || d.id) !== discussionId
        ),
      };
    });

    setCommunitiesList((prev) => {
      const updated = prev.map((c) => {
        if ((c._id || c.id) === commId) {
          return {
            ...c,
            discussions: (c.discussions || []).filter(
              (d) => (d._id || d.id) !== discussionId
            ),
          };
        }
        return c;
      });
      try {
        localStorage.setItem('planet_communities', JSON.stringify(updated));
      } catch { }
      return updated;
    });
  };

  // ==========================================
  // LIVE STREAM FEATURE STATE & HANDLERS
  // ==========================================
  const [liveStreamsList, setLiveStreamsList] = useState([]);
  const [isLoadingLiveStreams, setIsLoadingLiveStreams] = useState(false);
  const [liveCategoryFilter, setLiveCategoryFilter] = useState('All');

  // Go Live Setup State
  const [showGoLiveModal, setShowGoLiveModal] = useState(false);
  const [newStreamTitle, setNewStreamTitle] = useState('');
  const [newStreamCategory, setNewStreamCategory] = useState('General');
  const [isStartingBroadcast, setIsStartingBroadcast] = useState(false);
  const [goLiveError, setGoLiveError] = useState(null);

  // Active Broadcaster State
  const [myBroadcastStream, setMyBroadcastStream] = useState(null);
  const [broadcastDuration, setBroadcastDuration] = useState(0);
  const [isBroadcastCamOn, setIsBroadcastCamOn] = useState(true);
  const [isBroadcastMicOn, setIsBroadcastMicOn] = useState(true);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [broadcastChatInput, setBroadcastChatInput] = useState('');
  const [broadcastReactions, setBroadcastReactions] = useState([]);

  // Active Watcher State
  const [activeWatchingStream, setActiveWatchingStream] = useState(null);
  const [watchingChatInput, setWatchingChatInput] = useState('');
  const [watchingReactions, setWatchingReactions] = useState([]);

  // Media Refs
  const broadcasterVideoRef = useRef(null);
  const broadcasterMediaStreamRef = useRef(null);
  const broadcastTimerRef = useRef(null);

  const fetchLiveStreams = useCallback(async () => {
    setIsLoadingLiveStreams(true);
    try {
      const res = await fetch('/api/livestreams');
      if (res.ok) {
        const data = await res.json();
        if (data.streams) {
          setLiveStreamsList(data.streams);
        }
      }
    } catch (err) {
      console.warn('[Fetch Live Streams Error]:', err);
    } finally {
      setIsLoadingLiveStreams(false);
    }
  }, []);

  useEffect(() => {
    if (currentView === 'live-stream') {
      fetchLiveStreams();
    }
  }, [currentView, fetchLiveStreams]);

  useEffect(() => {
    return () => {
      if (broadcastTimerRef.current) clearInterval(broadcastTimerRef.current);
      if (broadcasterMediaStreamRef.current) {
        try {
          broadcasterMediaStreamRef.current.getTracks().forEach((t) => t.stop());
        } catch { }
      }
    };
  }, []);

  const formatBroadcastDuration = (totalSeconds) => {
    const hrs = Math.floor(totalSeconds / 3600);
    const mins = Math.floor((totalSeconds % 3600) / 60);
    const secs = totalSeconds % 60;
    if (hrs > 0) {
      return `${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
    }
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const triggerFloatingReaction = (emoji, isBroadcaster = false) => {
    const reaction = {
      id: 'react_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7),
      emoji,
      left: Math.floor(Math.random() * 55 + 20),
    };
    if (isBroadcaster) {
      setBroadcastReactions((prev) => [...prev.slice(-15), reaction]);
    } else {
      setWatchingReactions((prev) => [...prev.slice(-15), reaction]);
    }
    setTimeout(() => {
      if (isBroadcaster) {
        setBroadcastReactions((prev) => prev.filter((r) => r.id !== reaction.id));
      } else {
        setWatchingReactions((prev) => prev.filter((r) => r.id !== reaction.id));
      }
    }, 2200);
  };

  const handleStartBroadcast = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!newStreamTitle.trim()) {
      setGoLiveError('Please enter a stream title.');
      return;
    }
    setGoLiveError(null);
    setIsStartingBroadcast(true);

    let localStream = null;
    try {
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        localStream = await navigator.mediaDevices.getUserMedia({
          video: true,
          audio: true,
        }).catch(async (camErr) => {
          console.warn('[Camera error, trying audio-only]:', camErr);
          return await navigator.mediaDevices.getUserMedia({ audio: true }).catch(() => null);
        });
      }
    } catch (mediaErr) {
      console.warn('[Media permission error]:', mediaErr);
      localStream = null;
    }

    const hostUser = (loggedInUser || localStorage.getItem('assistance_user') || 'Creator').trim();
    const hostPic = profilePicture || localStorage.getItem('assistance_profile_picture') || '';

    try {
      const res = await fetch('/api/livestreams/start', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: newStreamTitle.trim(),
          category: newStreamCategory,
          host: hostUser,
          hostName: hostUser,
          hostAvatar: hostPic,
        }),
      });

      const data = await res.json();
      const createdStream = (data.success && data.stream) ? data.stream : {
        _id: 'live_' + Date.now(),
        title: newStreamTitle.trim(),
        category: newStreamCategory,
        host: hostUser,
        hostName: hostUser,
        hostAvatar: hostPic,
        status: 'live',
        viewerCount: 1,
        likesCount: 0,
        comments: [
          {
            id: 'c_welcome',
            user: 'system',
            userName: 'Planet Live',
            text: 'Welcome to your live broadcast! Live chat is now open.',
            createdAt: new Date(),
          }
        ],
        startedAt: new Date(),
      };

      broadcasterMediaStreamRef.current = localStream;
      setMyBroadcastStream(createdStream);
      setShowGoLiveModal(false);
      setNewStreamTitle('');
      setIsBroadcastCamOn(!!(localStream && localStream.getVideoTracks().length > 0 && localStream.getVideoTracks()[0].enabled));
      setIsBroadcastMicOn(!!(localStream && localStream.getAudioTracks().length > 0 && localStream.getAudioTracks()[0].enabled));
      setBroadcastDuration(0);

      setLiveStreamsList((prev) => [
        createdStream,
        ...prev.filter((s) => (s._id || s.id) !== (createdStream._id || createdStream.id)),
      ]);

      if (broadcastTimerRef.current) clearInterval(broadcastTimerRef.current);
      broadcastTimerRef.current = setInterval(() => {
        setBroadcastDuration((d) => d + 1);
      }, 1000);

      setTimeout(() => {
        if (broadcasterVideoRef.current && localStream) {
          try {
            broadcasterVideoRef.current.srcObject = localStream;
            broadcasterVideoRef.current.play().catch(() => { });
          } catch { }
        }
      }, 200);
    } catch (err) {
      console.error('[Error starting broadcast]:', err);
      setGoLiveError('Failed to start broadcast. Please try again.');
    } finally {
      setIsStartingBroadcast(false);
    }
  };

  const handleToggleCamera = () => {
    if (broadcasterMediaStreamRef.current) {
      const videoTracks = broadcasterMediaStreamRef.current.getVideoTracks();
      if (videoTracks.length > 0) {
        const nextState = !videoTracks[0].enabled;
        videoTracks.forEach((t) => { t.enabled = nextState; });
        setIsBroadcastCamOn(nextState);
      } else {
        setIsBroadcastCamOn((prev) => !prev);
      }
    } else {
      setIsBroadcastCamOn((prev) => !prev);
    }
  };

  const handleToggleMic = () => {
    if (broadcasterMediaStreamRef.current) {
      const audioTracks = broadcasterMediaStreamRef.current.getAudioTracks();
      if (audioTracks.length > 0) {
        const nextState = !audioTracks[0].enabled;
        audioTracks.forEach((t) => { t.enabled = nextState; });
        setIsBroadcastMicOn(nextState);
      } else {
        setIsBroadcastMicOn((prev) => !prev);
      }
    } else {
      setIsBroadcastMicOn((prev) => !prev);
    }
  };

  const handleToggleScreenShare = async () => {
    if (isScreenSharing) {
      if (broadcasterMediaStreamRef.current) {
        try {
          const camStream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true }).catch(() => null);
          if (camStream && broadcasterVideoRef.current) {
            broadcasterVideoRef.current.srcObject = camStream;
            broadcasterMediaStreamRef.current = camStream;
            setIsBroadcastCamOn(true);
          }
        } catch { }
      }
      setIsScreenSharing(false);
    } else {
      try {
        if (navigator.mediaDevices && navigator.mediaDevices.getDisplayMedia) {
          const screenStream = await navigator.mediaDevices.getDisplayMedia({ video: true });
          if (broadcasterVideoRef.current) {
            broadcasterVideoRef.current.srcObject = screenStream;
          }
          const screenTrack = screenStream.getVideoTracks()[0];
          if (screenTrack) {
            screenTrack.onended = () => {
              setIsScreenSharing(false);
            };
          }
          setIsScreenSharing(true);
        }
      } catch (err) {
        console.warn('[Screen share cancelled]:', err);
      }
    }
  };

  const handleEndBroadcast = async () => {
    if (!myBroadcastStream) return;
    const streamId = myBroadcastStream._id || myBroadcastStream.id;

    if (broadcasterMediaStreamRef.current) {
      try {
        broadcasterMediaStreamRef.current.getTracks().forEach((t) => t.stop());
      } catch { }
      broadcasterMediaStreamRef.current = null;
    }
    if (broadcasterVideoRef.current) {
      try {
        broadcasterVideoRef.current.srcObject = null;
      } catch { }
    }

    if (broadcastTimerRef.current) {
      clearInterval(broadcastTimerRef.current);
      broadcastTimerRef.current = null;
    }

    const hostUser = (loggedInUser || localStorage.getItem('assistance_user') || 'Creator').trim();
    try {
      await fetch(`/api/livestreams/${streamId}/end`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user: hostUser }),
      });
    } catch { }

    setMyBroadcastStream(null);
    setBroadcastDuration(0);
    setIsScreenSharing(false);
    setLiveStreamsList((prev) => prev.filter((s) => (s._id || s.id) !== streamId));
  };

  const handleSendBroadcastComment = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!broadcastChatInput.trim() || !myBroadcastStream) return;

    const streamId = myBroadcastStream._id || myBroadcastStream.id;
    const hostUser = (loggedInUser || localStorage.getItem('assistance_user') || 'Creator').trim();
    const commentText = broadcastChatInput.trim();
    setBroadcastChatInput('');

    const newComment = {
      id: 'c_' + Date.now(),
      user: hostUser,
      userName: hostUser,
      text: commentText,
      createdAt: new Date(),
    };

    setMyBroadcastStream((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        comments: [...(prev.comments || []), newComment],
      };
    });

    try {
      await fetch(`/api/livestreams/${streamId}/comment`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user: hostUser,
          userName: hostUser,
          text: commentText,
        }),
      });
    } catch { }
  };

  const handleSendBroadcastReaction = async (emoji) => {
    triggerFloatingReaction(emoji, true);
    if (!myBroadcastStream) return;
    const streamId = myBroadcastStream._id || myBroadcastStream.id;
    setMyBroadcastStream((prev) => prev ? { ...prev, likesCount: (prev.likesCount || 0) + 1 } : prev);
    try {
      await fetch(`/api/livestreams/${streamId}/react`, { method: 'POST' });
    } catch { }
  };

  const handleWatchStream = (stream) => {
    setActiveWatchingStream(stream);
  };

  const handleCloseWatchStream = () => {
    setActiveWatchingStream(null);
    setWatchingChatInput('');
    setWatchingReactions([]);
  };

  const handleSendWatcherComment = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!watchingChatInput.trim() || !activeWatchingStream) return;

    const streamId = activeWatchingStream._id || activeWatchingStream.id;
    const currentUser = (loggedInUser || localStorage.getItem('assistance_user') || 'Viewer').trim();
    const text = watchingChatInput.trim();
    setWatchingChatInput('');

    const newComment = {
      id: 'c_' + Date.now(),
      user: currentUser,
      userName: currentUser,
      text,
      createdAt: new Date(),
    };

    setActiveWatchingStream((prev) => {
      if (!prev) return prev;
      return {
        ...prev,
        comments: [...(prev.comments || []), newComment],
      };
    });

    setLiveStreamsList((prev) =>
      prev.map((s) => ((s._id || s.id) === streamId ? { ...s, comments: [...(s.comments || []), newComment] } : s))
    );

    try {
      await fetch(`/api/livestreams/${streamId}/comment`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          user: currentUser,
          userName: currentUser,
          text,
        }),
      });
    } catch { }
  };

  const handleSendWatcherReaction = async (emoji) => {
    triggerFloatingReaction(emoji, false);
    if (!activeWatchingStream) return;
    const streamId = activeWatchingStream._id || activeWatchingStream.id;

    setActiveWatchingStream((prev) =>
      prev ? { ...prev, likesCount: (prev.likesCount || 0) + 1 } : prev
    );

    setLiveStreamsList((prev) =>
      prev.map((s) => ((s._id || s.id) === streamId ? { ...s, likesCount: (s.likesCount || 0) + 1 } : s))
    );

    try {
      await fetch(`/api/livestreams/${streamId}/react`, { method: 'POST' });
    } catch { }
  };

